/** Base-language aliases: Norwegian "no" / Nynorsk "nn" use the Bokmål texts. */
const ALIAS = { no: "nb", nn: "nb" };

/** The built-in texts for a language ("fr-FR", "fr", "nb-NO" …), or null. */
export function moreTranslationsFor(lang) {
  const base = String(lang ?? "").toLowerCase().split("-")[0];
  return MORE_TRANSLATIONS[ALIAS[base] ?? base] ?? null;
}
